from pathlib import Path
import json
BASE=Path(__file__).resolve().parent/'output'
model=json.loads((BASE/'expanded_network.json').read_text())
js=(BASE.parent/'vendor/vis-network.min.js').read_text()
css=(BASE.parent/'vendor/vis-network.min.css').read_text()
data=json.dumps(model,ensure_ascii=False).replace('<','\\u003c')
html=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Included papers and their cited references</title><style>VISCSS
*{box-sizing:border-box}body{margin:0;font:14px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#203e50;background:#f6f8fa}header{padding:22px 28px 14px;background:white;border-bottom:1px solid #dce4eb}h1{font-size:26px;margin:0 0 8px}header p{margin:6px 0;color:#566e7e}.controls{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-top:15px}input,select,button{font:inherit;padding:9px 11px;border:1px solid #bdcdd8;border-radius:6px;background:white;color:#214e6d}input{width:440px;max-width:90vw}button{cursor:pointer}button:hover{background:#edf4f9}main{display:grid;grid-template-columns:minmax(0,1fr) 360px;height:calc(100vh - 220px);min-height:550px}#network{background:white}aside{padding:20px;overflow-y:auto;border-left:1px solid #dce4eb;background:#f9fbfc}aside h2{font-size:19px;margin-top:0}aside p{line-height:1.5}#neighbors button{display:block;text-align:left;width:100%;margin:7px 0;font-size:12px}.badge{display:inline-block;padding:4px 8px;background:#e6eff5;border-radius:4px;color:#326f99}.gold{background:#f6eddc;color:#8f611c}.legend{font-size:12px;color:#607789;margin-top:12px}#status{padding:10px 28px;font-size:13px;background:#edf3f7}a{color:#226286}#evidence{white-space:pre-wrap;font-size:12px;line-height:1.5;max-height:220px;overflow:auto}details{margin-top:14px}footer{font-size:12px;color:#607789;padding:10px 28px;border-top:1px solid #dce4eb}@media(max-width:900px){main{grid-template-columns:1fr;height:auto}#network{height:600px}aside{border-left:none;border-top:1px solid #dce4eb}}</style>
<header><h1>Included papers and their cited references</h1><p id="summary"></p><div class="controls"><input id="search" list="choices" aria-label="Find a paper or reference" placeholder="Find a paper ID, title, or reference…"><datalist id="choices"></datalist><button id="find">Inspect connections</button><select id="limit" aria-label="Number of external references"><option value="25">25 most-cited references</option><option value="50">50 most-cited references</option><option value="100">100 most-cited references</option><option value="all">All references</option></select><button id="reset">Overview</button><button id="fit">Fit view</button></div><div class="legend">◆ Blue: included papers &nbsp; ● Gold: cited references &nbsp; Arrows point from citing paper to cited work. Click a node for its details; double-click to isolate its connections.</div></header>
<div id="status" role="status"></div><main><div id="network" aria-label="Interactive historical citation network"></div><aside><h2 id="nodeTitle">Inspect the reference history</h2><div id="kind"></div><p id="nodeMeta">Search “Attention is all you need” to inspect a shared 2017 reference, or enter an included paper ID to see its bibliography.</p><p id="nodeId"></p><div id="links"></div><div id="neighbors"></div><details><summary>Scope and missing dates</summary><p id="scope"></p><p>The 45 included papers retain the review database's years. Five records differ from the verified citation registry; see the methods. References without a reliable year remain in an undated lane.</p><p>Reference identities were matched conservatively using identifiers and title/year evidence. Bibliographic versions may remain separate; the count is a reconstruction, not a global citation metric.</p></details><p><a href="network_nodes.csv" download>Download all nodes</a> · <a href="network_edges.csv" download>Download all links</a> · <a href="README.md">Methods</a></p></aside></main><footer>All data and graph code are embedded locally. The full data retain every extracted reference item; the overview limits displayed external references for readability.</footer>
<script>VISJS</script><script>
const model=__EMBEDDED_MODEL__;const nodesById=new Map(model.nodes.map(n=>[n.id,n]));const seeds=model.nodes.filter(n=>n.kind==='included');const refs=model.nodes.filter(n=>n.kind==='cited_reference');
const byOut=new Map(),byIn=new Map();for(const e of model.edges){if(!byOut.has(e.source))byOut.set(e.source,[]);byOut.get(e.source).push(e.target);if(!byIn.has(e.target))byIn.set(e.target,[]);byIn.get(e.target).push(e.source)}
const nodeData=new vis.DataSet(),edgeData=new vis.DataSet();const graph=new vis.Network(document.getElementById('network'),{nodes:nodeData,edges:edgeData},{physics:false,interaction:{hover:true,navigationButtons:true,keyboard:true},nodes:{font:{size:14,face:'Arial',strokeWidth:3,strokeColor:'#fff'},borderWidth:1},edges:{arrows:{to:{enabled:true,scaleFactor:.45}},color:{color:'#a3b3bf',highlight:'#244f6e'},width:.8,smooth:{enabled:true,type:'curvedCW',roundness:.06},selectionWidth:2},layout:{improvedLayout:false}});
document.getElementById('summary').textContent=`${seeds.length} included papers · ${refs.length.toLocaleString()} cited-reference nodes · ${model.edges.length.toLocaleString()} direct links · reference years ${model.counts.earliest_reference_year}–${model.counts.latest_reference_year}`;
document.getElementById('scope').textContent=`This is a one-step expansion of the 45 papers' reference lists. It does not infer citations among external references. ${model.counts.undated_reference_nodes} reference nodes have no reliable year.`;
for(const n of model.nodes){const op=document.createElement('option');op.value=n.short_id+' | '+(n.year||'undated')+' | '+n.title;op.dataset.id=n.id;document.getElementById('choices').appendChild(op)}
function render(ids,message){const list=model.nodes.filter(n=>ids.has(n.id));const dated=list.filter(n=>n.year);const min=Math.min(...dated.map(n=>n.year)),max=Math.max(...dated.map(n=>n.year));const buckets=new Map();for(const n of list){const yr=n.year||max+3;if(!buckets.has(yr))buckets.set(yr,[]);buckets.get(yr).push(n)}
nodeData.clear();edgeData.clear();const drawNodes=[],drawEdges=[];for(const [yr,group]of buckets){group.sort((a,b)=>a.short_id.localeCompare(b.short_id));for(let i=0;i<group.length;i++){const n=group[i],inc=n.kind==='included';drawNodes.push({id:n.id,label:n.short_id+'\n'+(n.year||'undated'),x:(yr-min)*180,y:(i-(group.length-1)/2)*54,shape:inc?'diamond':'dot',size:inc?11:Math.min(30,8+Math.sqrt(n.cited_by_count)*2.3),color:inc?'#326f99':'#bb842f',title:undefined})}}
let count=0;for(const e of model.edges){if(ids.has(e.source)&&ids.has(e.target)){drawEdges.push({id:count++,from:e.source,to:e.target})}}nodeData.add(drawNodes);edgeData.add(drawEdges);document.getElementById('status').textContent=`${message} · ${list.length} nodes and ${count} links displayed. Scroll to zoom; drag to pan.`;graph.fit({animation:false});}
function overview(){const lim=document.getElementById('limit').value;const included=lim==='all'?refs:refs.slice(0,Number(lim));render(new Set([...seeds,...included].map(n=>n.id)),lim==='all'?'Complete one-step network':'All 45 source papers with the '+lim+' most-cited external references');}
function inspect(id){const n=nodesById.get(id);if(!n)return;document.getElementById('nodeTitle').textContent=n.title;const kind=document.getElementById('kind');kind.className='badge'+(n.kind==='included'?'':' gold');kind.textContent=n.kind==='included'?'Included paper':'Cited reference';document.getElementById('nodeMeta').textContent=`Year: ${n.year||'unresolved'} · Cited by ${n.cited_by_count} of the included papers${n.observed_years.length>1?' · Observed year variants: '+n.observed_years.join(', '):''}`;document.getElementById('nodeId').textContent=n.short_id+' · '+n.id;const links=document.getElementById('links');links.replaceChildren();if(n.doi){const a=document.createElement('a');a.href='https://doi.org/'+n.doi;a.textContent='Open DOI record';a.target='_blank';a.rel='noopener';links.appendChild(a)}const box=document.getElementById('neighbors');box.replaceChildren();for(const [label,arr]of [['Cites',byOut.get(id)||[]],['Cited by',byIn.get(id)||[]]]){if(!arr.length)continue;const h=document.createElement('h3');h.textContent=label+' ('+arr.length+')';box.appendChild(h);for(const other of arr){const t=nodesById.get(other),button=document.createElement('button');button.textContent=t.short_id+' · '+(t.year||'undated')+' · '+t.title;button.onclick=()=>focus(other);box.appendChild(button)}}}
function focus(id){const ids=new Set([id,...(byOut.get(id)||[]),...(byIn.get(id)||[])]);render(ids,'Connections of '+nodesById.get(id).short_id);inspect(id);graph.selectNodes([id]);}
function find(){const q=document.getElementById('search').value.toLowerCase().trim();if(!q)return;const choice=[...document.getElementById('choices').options].find(o=>o.value.toLowerCase()===q);const n=choice?nodesById.get(choice.dataset.id):model.nodes.find(n=>n.id.toLowerCase()===q||n.short_id.toLowerCase()===q)||model.nodes.find(n=>n.title.toLowerCase().includes(q));if(n)focus(n.id);else document.getElementById('status').textContent='No matching title or ID found.';}
graph.on('click',p=>{if(p.nodes.length)inspect(p.nodes[0])});graph.on('doubleClick',p=>{if(p.nodes.length)focus(p.nodes[0])});document.getElementById('find').onclick=find;document.getElementById('search').onkeydown=e=>{if(e.key==='Enter')find()};document.getElementById('limit').onchange=overview;document.getElementById('reset').onclick=overview;document.getElementById('fit').onclick=()=>graph.fit({animation:false});overview();
</script></html>'''
html=html.replace('VISCSS',css).replace('VISJS',js).replace('__EMBEDDED_MODEL__',data,1)
(BASE/'reference_network_explorer.html').write_text(html)
print('Self-contained explorer saved:',len(html),'characters')
